from itertools import combinations
class Solution:
    def maximumTastiness(self, price: List[int], k: int) -> int:
        best = 0
        for comb in combinations(sorted(price), k):
            best = max(best, min(b - a for a, b in zip(comb, comb[1:])))
        return best

