class Solution {
    public int maximumTastiness(int[] price, int k) {
        Arrays.sort(price);
        return best(price, new int[k], 0, 0, Integer.MAX_VALUE);
    }
    private int best(int[] p, int[] cur, int start, int filled, int mn) {
        if (filled == k) return mn;
        int ans = 0;
        for (int i = start; i <= p.length - (k - filled); i++) {
            int nm = (filled == 0) ? mn : Math.min(mn, p[i] - cur[filled-1]);
            cur[filled] = p[i];
            ans = Math.max(ans, best(p, cur, i + 1, filled + 1, nm));
        }
        return ans;
    }
}

