var maximumTastiness = function(price, k) {
    price.sort((a, b) => a - b);
    let best = 0;
    const rec = (start, filled, prev, mn) => {
        if (filled === k) { best = Math.max(best, mn); return; }
        for (let i = start; i <= price.length - (k - filled); i++) {
            rec(i + 1, filled + 1, price[i],
                filled === 0 ? Infinity : Math.min(mn, price[i] - prev));
        }
    };
    rec(0, 0, 0, Infinity);
    return best;
};

