        price.sort()
        def ok(d):
            cnt, prev = 1, price[0]
            for p in price[1:]:
                if p - prev >= d:
                    cnt += 1; prev = p
                    if cnt >= k: return True
            return cnt >= k
        lo, hi = 0, (price[-1] - price[0]) // (k - 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid): lo = mid
            else: hi = mid - 1
        return lo

