class Solution {
public:
    int maximumTastiness(vector<int>& price, int k) {
        sort(price.begin(), price.end());
        auto ok = [&](long long d) {
            int cnt = 1; long long prev = price[0];
            for (int p : price)
                if (p - prev >= d) { cnt++; prev = p; if (cnt >= k) return true; }
            return cnt >= k;
        };
        long long lo = 0, hi = (price.back() - price.front()) / (k - 1);
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
};

