class Solution {
    public int maximumTastiness(int[] price, int k) {
        Arrays.sort(price);
        long lo = 0, hi = (price[price.length-1] - price[0]) / (k - 1);
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (ok(price, k, mid)) lo = mid;
            else hi = mid - 1;
        }
        return (int) lo;
    }
    private boolean ok(int[] p, int k, long d) {
        int cnt = 1; long prev = p[0];
        for (int x : p)
            if (x - prev >= d) { cnt++; prev = x; if (cnt >= k) return true; }
        return cnt >= k;
    }
}

